from pathlib import Path


def read(path: str) -> str:
    return Path(path).read_text(encoding="utf-8")


def write(path: str, text: str) -> None:
    Path(path).write_text(text, encoding="utf-8")


def replace_once(path: str, old: str, new: str) -> None:
    text = read(path)
    if old not in text:
        raise SystemExit(f"Anchor not found in {path}: {old[:160]!r}")
    write(path, text.replace(old, new, 1))


def replace_block(path: str, start: str, end: str, new_block: str) -> None:
    text = read(path)
    a = text.find(start)
    if a < 0:
        raise SystemExit(f"Start anchor not found in {path}: {start!r}")
    b = text.find(end, a)
    if b < 0:
        raise SystemExit(f"End anchor not found in {path}: {end!r}")
    write(path, text[:a] + new_block + text[b:])


